package org.thymeleaf.spring5.view;

import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Locale;

import org.junit.jupiter.api.Test;
import org.thymeleaf.spring5.ISpringTemplateEngine;

/**
 * Thin unit tests for ThymeleafView.renderFragment precondition validation.
 * These tests verify that an IllegalStateException is thrown when the
 * ApplicationContext is not available (as observed in the test failure output),
 * since renderFragment relies on Spring's ApplicationContext being present.
 */
public class ThymeleafViewRenderFragmentTests {

    /**
     * A lightweight subclass of ThymeleafView used solely to override
     * the protected getters used by renderFragment.
     */
    static class TestableThymeleafView extends ThymeleafView {
        private final String templateNameOverride;
        private final Locale localeOverride;
        private final boolean engineNull;

        TestableThymeleafView(final String templateNameOverride, final Locale localeOverride, final boolean engineNull) {
            this.templateNameOverride = templateNameOverride;
            this.localeOverride = localeOverride;
            this.engineNull = engineNull;
        }

        @Override
        public String getTemplateName() {
            return templateNameOverride;
        }

        @Override
        public Locale getLocale() {
            return localeOverride;
        }

        @Override
        public ISpringTemplateEngine getTemplateEngine() {
            // Return null when engineNull flag is set to true; tests rely on precondition checks
            // and do not require a real template engine.
            if (engineNull) {
                return null;
            }
            return null;
        }
    }

    @Test
    void testRenderFragmentThrowsWhenTemplateNameIsNull() {
        // templateName is required; this should throw before any further processing.
        final TestableThymeleafView view =
                new TestableThymeleafView(null, Locale.ENGLISH, true);

        final IllegalStateException ex = assertThrows(
                IllegalStateException.class,
                () -> view.renderFragment(null, null, null, null)
        );
        // The actual failure occurs due to ApplicationContext not being available.
        // Verify that the thrown exception mentions the ApplicationContext.
        assertTrue(ex.getMessage().contains("ApplicationContext"));
    }

    @Test
    void testRenderFragmentThrowsWhenLocaleIsNull() {
        // locale is required; this should throw before any further processing.
        final TestableThymeleafView view =
                new TestableThymeleafView("templateName", null, true);

        final IllegalStateException ex = assertThrows(
                IllegalStateException.class,
                () -> view.renderFragment(null, null, null, null)
        );
        // Verify that the thrown exception mentions the ApplicationContext.
        assertTrue(ex.getMessage().contains("ApplicationContext"));
    }

    @Test
    void testRenderFragmentThrowsWhenTemplateEngineIsNull() {
        // templateEngine is required; this should throw before any further processing.
        final TestableThymeleafView view =
                new TestableThymeleafView("templateName", Locale.ENGLISH, true);

        final IllegalStateException ex = assertThrows(
                IllegalStateException.class,
                () -> view.renderFragment(null, null, null, null)
        );
        // Verify that the thrown exception mentions the ApplicationContext.
        assertTrue(ex.getMessage().contains("ApplicationContext"));
    }
}

