    void returnsInputUnchangedWhenThereIsNoLiteralSubstitution() {
        final String input = "${user.name}";

        assertSame(input, LiteralSubstitutionUtil.performLiteralSubstitution(input));
    }

    @Test
    void convertsTextAndExpressionWithinLiteralSubstitutionToConcatenation() {
        assertEquals(
                "'Hello ' + ${name} + '!'",
                LiteralSubstitutionUtil.performLiteralSubstitution("|Hello ${name}!|"));
    }

    @Test
    void convertsAdjacentExpressionsWithAnEmptyLiteralBetweenThem() {
        assertEquals(
                "${first} + '' + ${second}",
                LiteralSubstitutionUtil.performLiteralSubstitution("|${first}${second}|"));
    }

    @Test
    void escapesTextLiteralDelimitersInsideSubstitutionText() {
        assertEquals(
                "'O\\'Reilly'",
                LiteralSubstitutionUtil.performLiteralSubstitution("|O'Reilly|"));
    }

    @Test
    void preservesAnEmptyLiteralSubstitution() {
        assertEquals(
                "before||||after",
                LiteralSubstitutionUtil.performLiteralSubstitution("before||||after"));
    }

    @Test
    void doesNotProcessPipesInsideAnExistingTextLiteral() {
        final String input = "'left|right'";

        assertSame(input, LiteralSubstitutionUtil.performLiteralSubstitution(input));
    }

    @Test
    void convertsAnUnpairedLiteralSubstitutionDelimiterToTextLiteralSyntax() {
        assertEquals(
                "prefix 'value",
                LiteralSubstitutionUtil.performLiteralSubstitution("prefix |value"));
    }
}

